import{_ as i,C as t,o as s,c as l,E as o,a2 as r}from"./chunks/framework.BhCQlvXS.js";const g=JSON.parse('{"title":"常见问题 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1786421207000}'),h={name:"faq.md"};function d(n,a,p,c,k,u){const e=t("VersionBadge");return s(),l("div",null,[o(e),a[0]||(a[0]=r(`<h1 id="常见问题-faq" tabindex="-1">常见问题 FAQ <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题 FAQ&quot;">​</a></h1><h2 id="扩展包选择" tabindex="-1">扩展包选择 <a class="header-anchor" href="#扩展包选择" aria-label="Permalink to &quot;扩展包选择&quot;">​</a></h2><h3 id="动作包还是插件" tabindex="-1">动作包还是插件？ <a class="header-anchor" href="#动作包还是插件" aria-label="Permalink to &quot;动作包还是插件？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>推荐形态</th></tr></thead><tbody><tr><td>只需要 Flow 编辑器里的可视化积木</td><td>动作包（<code>pack_type: action</code>）</td></tr><tr><td>需要侧边栏入口 + 独立功能页面</td><td>插件（<code>pack_type: plugin</code>）</td></tr><tr><td>先积木，以后可能加 UI</td><td>先用动作包，后续改为插件（manifest 改 pack_type + 补 sidebar/ui/rust_library）</td></tr></tbody></table><h3 id="lua-还是-rust" tabindex="-1">Lua 还是 Rust？ <a class="header-anchor" href="#lua-还是-rust" aria-label="Permalink to &quot;Lua 还是 Rust？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐执行器</th></tr></thead><tbody><tr><td>字符串处理、循环、逻辑判断、轻量计算</td><td>Lua</td></tr><tr><td>调用 Win32 API / 文件系统 / 网络 / 高性能计算</td><td>Rust（自定义 .dll）</td></tr><tr><td>调内置系统功能（关机/音量/进程/通知）</td><td>内置 ActionType（Rust，零代码）</td></tr></tbody></table><hr><h2 id="环境配置" tabindex="-1">环境配置 <a class="header-anchor" href="#环境配置" aria-label="Permalink to &quot;环境配置&quot;">​</a></h2><h3 id="cargo-target-dir-为什么要设" tabindex="-1">CARGO_TARGET_DIR 为什么要设？ <a class="header-anchor" href="#cargo-target-dir-为什么要设" aria-label="Permalink to &quot;CARGO_TARGET_DIR 为什么要设？&quot;">​</a></h3><p>Tauri 增量构建清理时会删除旧的 target 目录，删除的文件会进回收站。target 目录动辄几十 GB，回收站会爆。设置 <code>CARGO_TARGET_DIR=C:\\cargo-target-dominate</code> 把目标目录放到受控位置（在沙箱外，清理时永久删除不进回收站）。</p><div class="danger custom-block"><p class="custom-block-title">所有终端会话都要设</p><p>这是环境变量，不是配置文件。每个新 PowerShell 窗口打开后要<strong>重新设一次</strong>。推荐加到 PowerShell profile：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># $PROFILE 里加一行：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CARGO_TARGET_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\cargo-target-dominate&quot;</span></span></code></pre></div></div><h3 id="为什么-cargo-必须手动跑" tabindex="-1">为什么 cargo 必须手动跑？ <a class="header-anchor" href="#为什么-cargo-必须手动跑" aria-label="Permalink to &quot;为什么 cargo 必须手动跑？&quot;">​</a></h3><p>TRAE IDE 的 RunCommand 在 sandbox 中执行，sandbox 清理时会触发 cargo target 中的文件删除（导致回收站爆）。因此 cargo 命令一律在 <strong>TRAE IDE 终端（非 sandbox）</strong> 手动执行。</p><hr><h2 id="manifest-编写" tabindex="-1">Manifest 编写 <a class="header-anchor" href="#manifest-编写" aria-label="Permalink to &quot;Manifest 编写&quot;">​</a></h2><h3 id="pack-type-plugin-能不能只作为-ui-不声明-actions" tabindex="-1">pack_type: &quot;plugin&quot; 能不能只作为 UI 不声明 actions？ <a class="header-anchor" href="#pack-type-plugin-能不能只作为-ui-不声明-actions" aria-label="Permalink to &quot;pack_type: &quot;plugin&quot; 能不能只作为 UI 不声明 actions？&quot;">​</a></h3><p>可以。<code>actions[]</code> 不是插件必填（<code>sidebar</code> + <code>ui</code> 才是）。纯信息展示/配置面板类插件可以没有动作。</p><h3 id="同一个扩展包可以同时有-lua-和-rust-动作吗" tabindex="-1">同一个扩展包可以同时有 Lua 和 Rust 动作吗？ <a class="header-anchor" href="#同一个扩展包可以同时有-lua-和-rust-动作吗" aria-label="Permalink to &quot;同一个扩展包可以同时有 Lua 和 Rust 动作吗？&quot;">​</a></h3><p>可以。<code>actions[]</code> 里每个动作独立声明 <code>executor_type</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;actions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lua-a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;executor_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;executor_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;scripts/a.lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rust-b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;executor_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rust&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;executor_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rust_action_in_dll&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>注意：要 Rust 动作的话 manifest 根必须声明 <code>rust_library: &quot;xxx.dll&quot;</code>。</p><h3 id="怎么给图标-需要打包图片吗" tabindex="-1">怎么给图标？需要打包图片吗？ <a class="header-anchor" href="#怎么给图标-需要打包图片吗" aria-label="Permalink to &quot;怎么给图标？需要打包图片吗？&quot;">​</a></h3><p>不需要。图标字段 <code>icon</code> 是 <strong>lucide-react 图标名</strong>（纯字符串），Exero 前端内置此图标库。图标名大小写敏感。常用名：<code>Code</code> <code>AppWindow</code> <code>Volume2</code> <code>Puzzle</code> <code>Calculator</code> <code>Clock</code> <code>Globe</code>。</p><p>完整列表：<a href="https://lucide.dev/icons" target="_blank" rel="noreferrer">lucide.dev/icons</a></p><hr><h2 id="lua-开发" tabindex="-1">Lua 开发 <a class="header-anchor" href="#lua-开发" aria-label="Permalink to &quot;Lua 开发&quot;">​</a></h2><h3 id="能不能-require-其他-lua-文件" tabindex="-1">能不能 require 其他 lua 文件？ <a class="header-anchor" href="#能不能-require-其他-lua-文件" aria-label="Permalink to &quot;能不能 require 其他 lua 文件？&quot;">​</a></h3><p>默认沙箱禁用了 <code>require</code> + <code>package</code> + <code>dofile</code> + <code>loadfile</code>。方案：</p><ol><li>多个脚本写多个动作，通过 Flow 编排</li><li>全局变量传值（<code>exero.set_var(&quot;data&quot;, data, true)</code>）</li><li>放宽 <code>package</code> 权限（不推荐，官方市场大概率拒绝）</li></ol><h3 id="lua-变量的生命周期" tabindex="-1">Lua 变量的生命周期？ <a class="header-anchor" href="#lua-变量的生命周期" aria-label="Permalink to &quot;Lua 变量的生命周期？&quot;">​</a></h3><ul><li><strong>局部变量</strong>（<code>exero.set_var(&quot;x&quot;, 1)</code>）：单次 Flow 执行期间，从第一个动作到最后一个动作</li><li><strong>全局变量</strong>（<code>exero.set_var(&quot;x&quot;, 1, true)</code>）：同上，但所有动作可读可写</li><li><strong>执行结束</strong>：全部丢弃，不落盘</li></ul><p>需要持久化请：</p><ul><li>通过 Rust .dll 写外部数据库/文件</li><li>或在 Flow 开头 SetVariable 初始化 + 结尾 IfElse → 写文件动作</li></ul><h3 id="exero-set-result-返回值怎么在下一个动作读到" tabindex="-1">exero.set_result 返回值怎么在下一个动作读到？ <a class="header-anchor" href="#exero-set-result-返回值怎么在下一个动作读到" aria-label="Permalink to &quot;exero.set_result 返回值怎么在下一个动作读到？&quot;">​</a></h3><p>通过<strong>控制流的变量传递机制</strong>（非 <code>exero.get_var</code>）：</p><ul><li>在 React Flow 里：上一个动作节点 <code>output[done]</code> → 下一个动作节点 <code>input[trigger]</code> 连线</li><li>Rust 执行引擎在执行下一个动作前，把上一个结果写入局部变量空间</li><li>下一个 Lua 动作可通过 <code>args</code> 特殊字段 <code>__prev_result</code>（如声明了映射）读取</li></ul><p>最稳妥方案：上一个动作结束时 <code>exero.set_var(&quot;xxx&quot;, result)</code>，下一个动作开头 <code>local r = exero.get_var(&quot;xxx&quot;)</code>。</p><hr><h2 id="插件-ui" tabindex="-1">插件 UI <a class="header-anchor" href="#插件-ui" aria-label="Permalink to &quot;插件 UI&quot;">​</a></h2><h3 id="插件页面能用-vue-react-构建吗" tabindex="-1">插件页面能用 Vue/React 构建吗？ <a class="header-anchor" href="#插件页面能用-vue-react-构建吗" aria-label="Permalink to &quot;插件页面能用 Vue/React 构建吗？&quot;">​</a></h3><p>可以。iframe 中可以放任意前端构建产物。只要：</p><ol><li>最终产物是纯静态文件（HTML/CSS/JS）</li><li>entry HTML 中不要假设可以访问主窗口的 DOM/Storage</li></ol><p>推荐 Vite + React/Vue 构建后 <code>dist/</code> 内容全部进插件目录。</p><h3 id="插件-css-能沿用-shadcn-ui-吗" tabindex="-1">插件 CSS 能沿用 shadcn/ui 吗？ <a class="header-anchor" href="#插件-css-能沿用-shadcn-ui-吗" aria-label="Permalink to &quot;插件 CSS 能沿用 shadcn/ui 吗？&quot;">​</a></h3><p>主窗口和插件 iframe 完全隔离（无 <code>allow-same-origin</code>），插件 CSS 需要自己带。可以把 shadcn/ui 打包产物放进插件的 <code>assets/</code> 目录，然后 HTML <code>&lt;link rel=&quot;stylesheet&quot; href=&quot;assets/shadcn.css&quot;&gt;</code>。</p><h3 id="invoke-调用有超时限制吗" tabindex="-1">invoke 调用有超时限制吗？ <a class="header-anchor" href="#invoke-调用有超时限制吗" aria-label="Permalink to &quot;invoke 调用有超时限制吗？&quot;">​</a></h3><p>前端 Promise 端没有超时（硬上限 = Rust 端没做超时）。但：</p><ul><li>长耗时动作会卡住主窗口 UI（PluginPage 是同步 await）</li><li>推荐<strong>长耗时拆异步</strong>：Rust 端启动任务后立即返回 job_id，UI 轮询 <code>window.exero.invoke(&#39;get_status&#39;, {job_id})</code> 拿进度</li></ul><hr><h2 id="市场分发" tabindex="-1">市场分发 <a class="header-anchor" href="#市场分发" aria-label="Permalink to &quot;市场分发&quot;">​</a></h2><h3 id="market-index-json-能手动编辑吗" tabindex="-1">market-index.json 能手动编辑吗？ <a class="header-anchor" href="#market-index-json-能手动编辑吗" aria-label="Permalink to &quot;market-index.json 能手动编辑吗？&quot;">​</a></h3><p>能，但<strong>必须存为无 BOM UTF-8</strong>。Rust serde_json 不能解析带 BOM 的 JSON。</p><p>推荐：始终运行 <code>build-packs.ps1</code> 自动生成。手动编辑后用此命令检查：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$bytes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">System.IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::ReadAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\Market\\market-index.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$bom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0xEF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xBB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xBF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($bytes[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">..</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-eq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($bom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># $false = 正确，$true = 有 BOM</span></span></code></pre></div><h3 id="我是第三方开发者-想发布到官方市场" tabindex="-1">我是第三方开发者，想发布到官方市场？ <a class="header-anchor" href="#我是第三方开发者-想发布到官方市场" aria-label="Permalink to &quot;我是第三方开发者，想发布到官方市场？&quot;">​</a></h3><p>当前官方市场 = GitHub 仓库 ansoukin/Exero 的 <code>Market/</code> 目录。提交 PR 把 <code>.exero-pack</code> 加到对应目录并更新 index，CR 后合入即可。</p><p>未来（Beta7+）计划支持第三方市场源（多个 index.json URL 配置）。</p><hr><h2 id="版本兼容性" tabindex="-1">版本兼容性 <a class="header-anchor" href="#版本兼容性" aria-label="Permalink to &quot;版本兼容性&quot;">​</a></h2><h3 id="升级-exero-后旧扩展包用不了" tabindex="-1">升级 Exero 后旧扩展包用不了？ <a class="header-anchor" href="#升级-exero-后旧扩展包用不了" aria-label="Permalink to &quot;升级 Exero 后旧扩展包用不了？&quot;">​</a></h3><p>检查：</p><ol><li>扩展包 <code>exero_api_version</code> 在新版本兼容区间内（Beta6 兼容所有 <code>0.4.x</code>）</li><li>Manifest 结构没变（Beta5 重构过一次扩展机制，<code>pack_type</code> 字段有变化）</li><li>插件重新编译 .dll（Beta6 Rust MSRV 没升，但 linker 改动可能导致旧 dll 加载失败）</li></ol><h3 id="如何知道当前文档适用哪个-exero-版本" tabindex="-1">如何知道当前文档适用哪个 Exero 版本？ <a class="header-anchor" href="#如何知道当前文档适用哪个-exero-版本" aria-label="Permalink to &quot;如何知道当前文档适用哪个 Exero 版本？&quot;">​</a></h3><p>本套文档每页顶部都有 <code>适用版本：V0.4.0-Beta6</code> 徽章。前后端每次 Beta 变更时需同步更新徽章版本号和对应文档内容。</p><hr><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><h3 id="lua-动作-10-秒超时能调吗" tabindex="-1">Lua 动作 10 秒超时能调吗？ <a class="header-anchor" href="#lua-动作-10-秒超时能调吗" aria-label="Permalink to &quot;Lua 动作 10 秒超时能调吗？&quot;">​</a></h3><p>Beta6 不支持（硬编码 <code>10_000</code> ms）。需要更长执行时间请写 Rust 动作。</p><h3 id="插件-dll-越大加载越慢" tabindex="-1">插件 .dll 越大加载越慢？ <a class="header-anchor" href="#插件-dll-越大加载越慢" aria-label="Permalink to &quot;插件 .dll 越大加载越慢？&quot;">​</a></h3><p>是的。libloading <code>Library::new()</code> 加载后需做一次 C ABI 符号查找（4 个导出函数）。</p><ul><li>经验：&lt; 10MB 的 dll 加载 &lt; 50ms</li><li>建议：不要把不需要的 crate（如 tokio runtime、clap、tracing）编进去</li></ul><h3 id="扩展包装多了启动会慢吗" tabindex="-1">扩展包装多了启动会慢吗？ <a class="header-anchor" href="#扩展包装多了启动会慢吗" aria-label="Permalink to &quot;扩展包装多了启动会慢吗？&quot;">​</a></h3><p>启动时扫描三目录（builtin/user/custom）+ 解析 manifest + .dll 加载。</p><ul><li>50 个扩展包以内：&lt; 200ms</li><li>50+ .dll 插件：每多 1 个 dll 约加 10~50ms，建议控制数量</li></ul><hr><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><h3 id="dll-插件是安全的吗" tabindex="-1">.dll 插件是安全的吗？ <a class="header-anchor" href="#dll-插件是安全的吗" aria-label="Permalink to &quot;.dll 插件是安全的吗？&quot;">​</a></h3><p>.dll 加载<strong>无沙箱</strong>，可完全访问系统（与 Lua 宽松沙箱同级风险）。用户安装第三方插件时 Exero 会显示风险提示。官方市场的插件由 maintainer review 后合入。</p><h3 id="插件能读取-exero-的数据库吗" tabindex="-1">插件能读取 Exero 的数据库吗？ <a class="header-anchor" href="#插件能读取-exero-的数据库吗" aria-label="Permalink to &quot;插件能读取 Exero 的数据库吗？&quot;">​</a></h3><p>间接可以（.dll 端自己开 rusqlite 连接读 SQLite 文件路径）。但 Beta6 不提供&quot;官方数据库访问 API&quot;——这是有意为之的隔离边界。如果确实需要：</p><ul><li>读：自己找 <code>%APPDATA%\\Exero\\exero.db</code></li><li>写：不推荐，可能写坏主程序状态。用 invoke 返回给主程序，主程序再写入</li></ul><hr><h2 id="与-spec-的关系" tabindex="-1">与 SPEC 的关系 <a class="header-anchor" href="#与-spec-的关系" aria-label="Permalink to &quot;与 SPEC 的关系&quot;">​</a></h2><h3 id="spec-md-和这套文档看哪个" tabindex="-1">SPEC.md 和这套文档看哪个？ <a class="header-anchor" href="#spec-md-和这套文档看哪个" aria-label="Permalink to &quot;SPEC.md 和这套文档看哪个？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对象</th><th>推荐阅读</th></tr></thead><tbody><tr><td>扩展包开发者（写插件/动作包）</td><td><strong>本套 VitePress 文档</strong>（面向开发，完整示例 + API 参考）</td></tr><tr><td>改 Exero 核心代码</td><td>先读 <a href="/Exero/docs/spec-summary">SPEC 摘要</a>（5 分钟关键决策），细节查 SPEC.md</td></tr><tr><td>AI 协作助手</td><td>先读 SPEC 摘要 + <a href="/Exero/docs/architecture">架构概览</a>（减少 token 消耗），缺细节再读 SPEC.md 具体章节</td></tr></tbody></table>`,85))])}const q=i(h,[["render",d]]);export{g as __pageData,q as default};
